import apiClient from './client'
import type { Page, PageParams } from './page'

export type NotificationChannelType =
  | 'email'
  | 'webhook'
  | 'dingtalk'
  | 'wecom'
  | 'lark'
  | 'slack'

export interface NotificationChannelRead {
  id: number
  name: string
  channel_type: NotificationChannelType
  enabled: boolean
  config: Record<string, unknown>
  created_at: string
  updated_at: string
}

export interface NotificationChannelCreate {
  name: string
  channel_type: NotificationChannelType
  enabled?: boolean
  config: Record<string, unknown>
}

export interface NotificationChannelUpdate {
  name?: string
  channel_type?: NotificationChannelType
  enabled?: boolean
  config?: Record<string, unknown>
}

export interface TestChannelPayload {
  payload?: Record<string, unknown>
}

export interface TestChannelResponse {
  success: boolean
  message: string
  log_id?: number | null
}

export interface NotificationChannelListParams extends PageParams {
  channel_type?: NotificationChannelType
  enabled?: boolean
}

export async function getNotificationChannels(
  params?: NotificationChannelListParams
): Promise<Page<NotificationChannelRead>> {
  const response = await apiClient.get<Page<NotificationChannelRead>>('/v1/notification-channels', {
    params,
  })
  return response.data
}

export async function createNotificationChannel(
  data: NotificationChannelCreate
): Promise<NotificationChannelRead> {
  const response = await apiClient.post<NotificationChannelRead>('/v1/notification-channels', data)
  return response.data
}

export async function getNotificationChannel(channelId: number): Promise<NotificationChannelRead> {
  const response = await apiClient.get<NotificationChannelRead>(`/v1/notification-channels/${channelId}`)
  return response.data
}

export async function updateNotificationChannel(
  channelId: number,
  data: NotificationChannelUpdate
): Promise<NotificationChannelRead> {
  const response = await apiClient.put<NotificationChannelRead>(
    `/v1/notification-channels/${channelId}`,
    data
  )
  return response.data
}

export async function deleteNotificationChannel(channelId: number): Promise<void> {
  await apiClient.delete(`/v1/notification-channels/${channelId}`)
}

export async function testNotificationChannel(
  channelId: number,
  data?: TestChannelPayload
): Promise<TestChannelResponse> {
  const response = await apiClient.post<TestChannelResponse>(
    `/v1/notification-channels/${channelId}/test`,
    data || {}
  )
  return response.data
}
